void HandlerAsyncWaiter::GetReports(
    std::vector<WebUIAggregatableReportPtr>* out_reports) {
  base::RunLoop loop;
  proxy_->GetReports(
      base::BindOnce(
          [](base::RunLoop* loop,
             std::vector<WebUIAggregatableReportPtr>* out_reports
,
             std::vector<WebUIAggregatableReportPtr> reports) {*out_reports = std::move(reports);
            loop->Quit();
          },
          &loop,
          out_reports));
  loop.Run();
}

